#pragma once
/**
 * @file RxClockCarry.hpp
 * @brief The receiver-clock carry family (RX-CLK-in-block): the in-block columns.
 *
 * A family file of PASS B's station build: the steps of the family in
 * kStationBuildSteps / kStationCarrySteps (network/assembly/StationBuild.hpp), generated by
 * scripts/nom_pb1b_cut.py from the frozen text of networkPassB_'s produce loop.
 *
 * The harvest half (generated by scripts/nom_hv1_cut.py, checked by
 * scripts/nom_hv1_verify.py) is the family's post-solve harvest, stash and prune, called by
 * networkHarvestLocalCarries (network/carry/LocalCarryHarvest.hpp, its table of contents).
 */

#include <cstdint>
#include <cstddef>
#include <vector>

namespace GnssProcessor {

struct NetworkRunEndView;

// ---- PASS B station steps, declarations (generated by scripts/nom_pb1b_cut.py) ----

struct StationBuild;                       // network/assembly/StationBuild.hpp
struct StationCarryFrame;                  // network/assembly/StationBuild.hpp
enum class StationStep : std::uint8_t;     // network/assembly/StationBuild.hpp

/**
 * @brief RX-CLK-in-block: the station's carried receiver-clock columns for the local block.
 *
 * Step `rx_clock_block` of kStationCarrySteps (network/assembly/StationBuild.hpp); its kinds: none
 * (it records only). It returns at once unless the frozen enclosing conditions
 * legacy_local_inject && do_amb_carry. Records: pl_rxclk and its gap counters; rxclk_bc,
 * rxclk_pred. The frozen text of networkPassB_'s produce loop below its bindings (card NOM3
 * step PB1b).
 * @param carry The station's carry frame (the build, the priors, the coupling builder, the
 *              block columns).
 */
void networkRxClockBlockColumns(StationCarryFrame& carry);

// ---- End of the PASS B station steps, declarations ----

// ---- Harvest half, declarations (generated by scripts/nom_hv1_cut.py) ----

struct NetworkRun;                          // network/driver/Run.hpp
struct NetworkEpoch;                        // network/driver/Epoch.hpp
struct HarvestBorder;                       // network/carry/LocalCarryHarvest.hpp
struct StationHarvestBlock;                 // network/carry/LocalCarryHarvest.hpp

/**
 * @brief network.carry_rx_clock_in_block: receiver clock and ISB columns with their F3 rows; the
 *        primary clock's (bias, drift) filter, its gate census and jump response; the prune.
 *
 * @param run The run: its context (carry, counters, knobs), setup (stations) and engines.
 * @param ep This epoch after the solve (the solution, the assembly, the columns and the clock are
 *           read; nothing is written).
 * @param border This harvest's shared border (column identities, datum-frame covariance, the clone
 *               and shared-history handles).
 * @param blocks Every station's harvest layout, by station index (ok false: not harvested).
 */
void networkHarvestRxClock(NetworkRun& run, const NetworkEpoch& ep, HarvestBorder& border,
                           const std::vector<StationHarvestBlock>& blocks);

// ---- End of the harvest half, declarations ----

/**
 * @brief Run-end report: the receiver-clock carry's jump gate, in metres (card NOM2 step
 *        TD2: moved from the leveling-carry retirement report).
 *
 * The gate k sigma over the station-epoch tests, its mean, minimum and maximum in metres,
 * the largest |innovation| seen and the refusals, so a given step reads as above or
 * below the gate.
 *
 * Gate: `config_.networkCarryRxClockInBlock()`.
 *
 * @param v The run at its end (network/runend/RunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkRxClockCarryRunEnd(const NetworkRunEndView& v);

} // namespace GnssProcessor
